### main.js
```js
const fs = require('fs');
const path = require('path');
const axios = require('axios');
const ffmpeg = require('fluent-ffmpeg');
const sharp = require('sharp');
const { addTextToImage } = require('./utils');

// Load configuration
const configPath = path.join(__dirname, 'config.json');
const config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));

async function downloadAndProcessFrames() {
  const frames = config.frames;
  for (const frame of frames) {
    // Download image
    const imagePath = path.join(__dirname, `frame-${frames.indexOf(frame)}.jpg`);
    await downloadFile(frame.image, imagePath);

    // Add text to image
    const textAddedImagePath = path.join(__dirname, `frame-text-added-${frames.indexOf(frame)}.jpg`);
    await addTextToImage(imagePath, frame.text, textAddedImagePath);

    console.log(`Frame ${frames.indexOf(frame)} processed.`);
  }

  // Combine images into video
  const videoOutputPath = path.join(__dirname, 'output.mp4');
  combineImagesIntoVideo(frames.map((_, index) => path.join(__dirname, `frame-text-added-${index}.jpg`)), videoOutputPath);
}

async function downloadFile(url, dest) {
  const response = await axios({
    url: url,
    method: 'GET',
    responseType: 'stream'
  });
  return new Promise((resolve, reject) => {
    response.data.pipe(fs.createWriteStream(dest)).on('finish', resolve).on('error', reject);
  });
}

function CombineImagesIntoVideo(images, outputPath) {
  ffmpeg(images)
    .fps(1) // Set frames per second
    .size('HD') //Set resolution
    .output(outputPath)
    .on('end', () => console.log('Video creation complete.'))
    .run();
}

downloadAnd ProcessFrames().catch(console.error);
```

### utils.js
```js
const sharp = require('sharp');
const { createCanvas, loadImage } = require('canvas');
const Canvas = createCanvas;
const ctx = Canvas(1280, 720).getContext('d');
require('text-to-video');

async function addTextToImage(imagePath, text, outputImagePath) {
  // Load image
  const imageBuffer = await sharp(imagePath)..toBuffer()
  ctx.drawImage(await loadImage(imageBuffer), 0, 0);

  // Draw text
  ctx.font = 'bold 24px Arial';
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillTextext, 640, 672); // Center text

  // Save modified image
  const buffer = ctx.getImagedata(0, 0, 1280, 720).toBuffer();
  await sharp(buffer).toFile(outputImagePath);
}

module.exports = { addTextToImage };
```

